-- scripts/build10_hashes.sql  (build 10, check 5)
-- Row count and two content hashes of every object of the rebuilt lanes HHG and
-- HERSHA: staging and transformation tables, classification rows, SEM slices.
--   content_hash  full content (RUN_ID, or LAST_SEEN_RUN_ID, excluded)
--   rest_hash     also excluding every column this build may change:
--                 ASSET_NAME, ASSET_NAME_SOURCE, ACCOUNT_DESC, IS_SUBTOTAL,
--                 SUBTOTAL_SOURCE, UNKNOWN_REASON, H1-H5, P_L_SECTION,
--                 NORMAL_BALANCE, VALUE_SIGN, VALUE, METRIC_UNIT,
--                 AGGREGATION_TYPE, SEED_SOURCE
-- Taken before the first redeploy (33 objects), and the 5 staging tables new in build
-- 10 (M3) are appended. 38 objects.
-- ============================================================================
